<?php $editing = isset($info) && $info !== null; ?><form method="post" enctype="multipart/form-data" action="<?= htmlspecialchars(url_for('kunden/' . (int) $customer->id . '/infos'), ENT_QUOTES) ?>" class="row g-3"><input type="hidden" name="id" value="<?= $editing ? (int) $info->id : 0 ?>"><div class="col-12"><label class="form-label" for="customer-info-title">Titel</label><input class="form-control" id="customer-info-title" name="title" required value="<?= $editing ? htmlspecialchars((string) $info->title) : '' ?>" placeholder="z. B. Prüfablauf oder Sicherheitsinformationen"></div><?php if ($editing && str_starts_with((string) $info->file_mime, 'image/')): ?><div class="col-12"><label class="form-label">Aktuelles Bild</label><img class="img-fluid rounded border d-block customer-info-edit-preview" src="<?= htmlspecialchars(url_for('kundeninfos/' . (int) $info->id . '/datei'), ENT_QUOTES) ?>" alt="<?= htmlspecialchars((string) $info->title) ?>"></div><?php endif; ?><div class="col-12"><label class="form-label" for="customer-info-markdown">Info (Markdown)</label><textarea class="form-control font-monospace" id="customer-info-markdown" name="markdown" rows="12" placeholder="# Überschrift\n\nText, **wichtige Hinweise** oder [Link](https://example.org)"><?= $editing ? htmlspecialchars((string) $info->markdown) : '' ?></textarea><div class="form-text">Überschriften, Listen, Links und Fettdruck. Die Vorschau zeigt die Darstellung für Nutzer.</div><div id="customer-info-preview" class="border rounded p-3 mt-2 bg-body-tertiary" aria-live="polite">Vorschau erscheint hier.</div></div><div class="col-12"><label class="form-label" for="customer-info-attachment">Bild oder PDF</label><input class="form-control" id="customer-info-attachment" type="file" name="attachment" accept="application/pdf,image/jpeg,image/png,image/webp,image/gif"><?php if ($editing && trim((string) $info->file_name) !== ''): ?><div class="form-text">Aktuell: <?= htmlspecialchars((string) $info->file_name) ?> · Eine neue Datei ersetzt die bisherige.</div><?php endif; ?></div><div class="col-12 d-flex justify-content-end gap-2"><a class="btn btn-outline-secondary" href="<?= htmlspecialchars(url_for('kunden/' . (int) $customer->id . '/infos'), ENT_QUOTES) ?>">Abbrechen</a><button class="btn btn-primary">Speichern</button></div></form><style>.customer-info-edit-preview{max-height:360px;object-fit:contain;background:var(--bs-tertiary-bg)}</style><script>(()=>{const input=document.getElementById('customer-info-markdown'),preview=document.getElementById('customer-info-preview');if(!input||!preview)return;const render=()=>{let s=input.value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/^### (.+)$/gm,'<h5>$1</h5>').replace(/^## (.+)$/gm,'<h4>$1</h4>').replace(/^# (.+)$/gm,'<h3>$1</h3>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/^[-*] (.+)$/gm,'• $1').replace(/\n/g,'<br>');preview.innerHTML=s||'Vorschau erscheint hier.'};input.addEventListener('input',render);render()})();</script>
